INSERT INTO persona (
  idcargo_trabajador, codigo, tipo_persona_sunat, tipo_documento, numero_documento,
  descripcion, nombre_comercial, nombre_persona_natural, apellido_paterno_persona_natural,
  apellido_materno_persona_natural, fecha_nacimiento, nacionalidad, estado_civil,
  celular, direccion, direccion_referencia, iddistrito, cod_ubigeo, correo, sexo,
  numero_licencia, placa_vehiculo, foto_perfil, estado_trash, created_at, updated_at,
  user_trash, user_created, user_updated
)
SELECT
  (SELECT idpersona_cargo FROM persona_cargo WHERE nombre = 'SUPER ADMINISTRADOR' ORDER BY idpersona_cargo LIMIT 1),
  '00001', 'natural', '1', '20610724354', 'JDL Tecnology SAC', 'JDL Tecnology',
  'JDL', 'Tecnology', 'SAC', NULL, 'PERUANA', NULL, NULL, NULL, NULL, NULL, NULL,
  'jdltechnology19@gmail.com', NULL, NULL, NULL, NULL, '1', NOW(), NOW(), NULL, 1, 1
WHERE NOT EXISTS (SELECT 1 FROM persona WHERE correo = 'jdltechnology19@gmail.com');

