INSERT INTO users (
  idpersona, name, email, email_verified_at, password, remember_token, estado_trash,
  created_at, updated_at, user_trash, user_created, user_updated, user_update_sistema
)
VALUES (
  (SELECT idpersona FROM persona WHERE correo = 'jdltechnology19@gmail.com' ORDER BY idpersona LIMIT 1),
  'JDL Tecnology', 'jdltechnology19@gmail.com', NOW(),
  '$2y$12$7f.J8E.68DUPUhLUZ6tVO.rrEPIEqxpl0sRZeNohde/EAnf1WfHW.',
  NULL, '1', NOW(), NOW(), NULL, 1, 1, '1'
)
ON DUPLICATE KEY UPDATE
  idpersona = VALUES(idpersona),
  name = VALUES(name),
  email_verified_at = VALUES(email_verified_at),
  password = VALUES(password),
  estado_trash = VALUES(estado_trash),
