  user_updated = VALUES(user_updated),
  user_update_sistema = VALUES(user_update_sistema);

-- =========================================================
-- 5. Marcar la persona inicial como trabajador
-- =========================================================

INSERT INTO persona_tipo_persona (idpersona, idpersona_tipo, created_at, updated_at, user_created, user_updated)
SELECT p.idpersona, pt.idpersona_tipo, NOW(), NOW(), u.id, u.id
FROM persona p
INNER JOIN users u ON u.idpersona = p.idpersona
INNER JOIN persona_tipo pt ON pt.nombre = 'TRABAJADOR'
WHERE u.email = 'jdltechnology19@gmail.com'
  AND NOT EXISTS (
    SELECT 1 FROM persona_tipo_persona ptp
    WHERE ptp.idpersona = p.idpersona
      AND ptp.idpersona_tipo = pt.idpersona_tipo
  );

-- =========================================================
-- 6. Dar todos los permisos de pagina al usuario inicial
-- =========================================================

UPDATE usuario_permiso up
INNER JOIN users u ON u.id = up.idusers
INNER JOIN permiso p ON p.idpermiso = up.idpermiso
SET up.crear = '1', up.editar = '1', up.eliminar = '1',
    up.estado_trash = '1', up.user_trash = NULL, up.user_updated = u.id, up.updated_at = NOW()
WHERE u.email = 'jdltechnology19@gmail.com'
  AND COALESCE(p.estado_trash, '1') = '1'
  AND p.tipo = 'pagina'
  AND up.estado_trash = '1';

INSERT INTO usuario_permiso (
  idusers, idpermiso, crear, editar, eliminar, estado_trash,
  user_trash, created_at, updated_at, user_created, user_updated
)
SELECT u.id, p.idpermiso, '1', '1', '1', '1', NULL, NOW(), NOW(), u.id, u.id
FROM users u
INNER JOIN permiso p ON COALESCE(p.estado_trash, '1') = '1' AND p.tipo = 'pagina'
WHERE u.email = 'jdltechnology19@gmail.com'
  AND NOT EXISTS (
    SELECT 1 FROM usuario_permiso up
    WHERE up.idusers = u.id
      AND up.idpermiso = p.idpermiso
      AND up.estado_trash = '1'
  );


